//! This module contains scaffolding for baked providers, typically generated by
//! databake.
//!
//! It can be glob-imported, and includes the icu_provider prelude.
//!
//! This needs the `"export"` Cargo feature to be enabled.
import type { DataPayload } from "./response.ts";
import type { DataIdentifierBorrowed } from "./request.ts";

// pub mod zerotrie;
export * as zerotrie from "./baked/zerotrie.ts";

/// A backing store for baked data
export interface DataStore<T> {
  /// Get the value for a key
  // crate: icu_provider-2.3.0/src/baked.rs:18 get
  get(req: DataIdentifierBorrowed, attributes_prefix_match: boolean): DataPayload<T> | undefined;
}
